using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class GiovanniPascoli
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Chi ha toccato una volta un'ingiuria – di sangue e di morte – non cesserà mai di toccarne di nuove. Piove sul bagnato: lagrime su sangue, e sangue su lagrime.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Conoscere e descrivere la mente di Dante sarà mai possibile? Egli eclissa nella profondità del suo pensiero: volontariamente eclissa.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Delle città dove sono stato, Matera è quella che mi sorride di più, quella che vedo meglio ancora, attraverso un velo di poesia e di malinconia.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Di quercia caduta ognuno viene a far legna. E tagliato l'albero, così grande e bello, perché hanno a sopravvivere i novelli?", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Egli sembra, anche nell'aspetto, una di quelle foreste sul lido del suo mare, le quali anche nella più quieta serenità pare che si contorcano alle raffiche del libeccio.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Il paese non è grande, ma nemmeno piccolo; l'aria ottima; pittoreschi i dintorni: le rovine di Grumentum a pochi passi; arpeggiamenti per tutto, che fanno di Viggiano l'Antissa della Lucania.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Io sono un testimone; e ai testimoni non si chiede altezza d'ingegno e abbondanza di dottrina: si chiede se ha veduto e sa.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Al mio cantuccio, donde non sento | se non le reste brusir del grano | il suon dell'ore viene col vento | dal non veduto borgo montano.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Che torbida notte di marzo! | Ma che mattinata tranquilla! | che cielo pulito! Che sfarzo | di perle! Ogni stelo, una stilla | che ride: sorriso che brilla | su lunghe parole.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Egli coglieva ed ammucchiava al suolo | secche le foglie del suo marzo primo | (era il suo nuovo marzo), il rosignolo, || per farsi il nido. E gorgheggiava in tanto | tutto il gran giorno; e dolce più del timo | e più puro dell'acqua era il suo canto.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Io sono una lampada ch'arda | soave! | La lampada, forse, che guarda, | pendendo alla fumida trave, | la veglia che fila; || e ascolta novelle e ragioni | da bocche | celate nell'ombra, ai cantoni, | da dietro le soffici ròcche | che albeggiano in fila.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Per le faggete e l'abetine, | dalle fratte e dal ruscello, | quel canto suona senza fine, | chiaro come un campanello. | Per l'abetine e le faggete | canta, ogni ora ogni dì più, | la cinciallegra e ti ripete: | tient'a su! tient'a su! tient'a su!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "La Chioccetta per l'aia azzurra | va col suo pigolio di stelle.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "La vergine dorme. Ma lenta | la fiamma del puro alabastro | le immemori palpebre tenta; | bussa alla chiusa anima", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Lascia che guardi dentro al mio cuore | lascia ch'io viva del mio passato; | se c'è sul bronco sempre quel fiore, | s'io trovi un bacio che non ho dato! | Nel mio cantuccio d'ombra romita | lascia ch'io pianga sulla mia vita!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Nascondi le cose lontane, | tu nebbia impalpabile e scialba, | tu fumo che ancora rampolli, | su l'alba, | da' lampi notturni e da' crolli | d'aeree frane!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Oh! Valentino vestito di nuovo, | come le brocche dei biancospini! | Solo, ai piedini provati dal rovo | porti la pelle de' tuoi piedini || Porti le scarpe che mamma ti fece, | che non mutasti mai da quel dì, | che non costarono un picciolo: in vece | costa il vestito che ti cucì", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Non l'età grave impedisce di udire la vocina del bimbo interiore, anzi invita forse e aiuta, mancando l'altro chiasso intorno, ad ascoltarla nella penombra dell'anima.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Tu sei ancora in presenza del mondo novello, e adoperi a significarlo la novella parola. Il mondo nasce per ognun che nasce al mondo. E in ciò è il mistero della tua essenza e della tua funzione. Tu sei antichissimo, o fanciullo! E vecchissimo è il mondo che tu vedi nuovamente!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "A te né le gemme né gli ori | fornisco, o dolce ospite: è vero; | ma fo che ti bastino i fiori | che cogli nel verde sentiero, | nel muro, su le umide crepe, | su l'ispida siepe.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "la poesia, non ad altro intonata che a poesia, è quella che migliora e rigenera l'umanità, escludendone, non di proposito il male, ma naturalmente l'impoetico.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Il poeta, se è e quando è veramente poeta, cioè tale che significhi solo ciò che il fanciullo detta dentro, riesce perciò ispiratore di buoni e civili costumi, d'amor patrio e familiare e umano.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Il poeta è colui che esprime la parola che tutti avevano sulle labbra e che nessuno avrebbe detta. Ma non è lui che sale su una sedia o su un tavolo, ad arringare. Egli non trascina, ma è trascinato; non persuade, ma è persuaso.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Qualunque soggetto può essere contemplato, dagli occhi profondi del fanciullo interiore: qualunque tenue cosa può a quelli occhi parere grandissima.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "La poesia non si evolve e involve, non cresce o diminuisce; è una luce o un fuoco che è sempre quella luce e quel fuoco: i quali, quando appariscono, illuminano e scaldano ora come una volta, e in quel modo stesso.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "La poesia benefica di per sé, la poesia che di per sé ci fa meglio amare la patria, la famiglia, l'umanità, è, dunque, la poesia pura, la quale di rado si trova.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "La poesia consiste nella visione d'un particolare inavvertito, fuori e dentro di noi.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Oh! come è necessaria l'imperfezione per essere perfetti!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Gli occhi della gente sono oggi così fissi nell'ombelico della propria persona, che non hanno visto, si può dire, altro.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Ricòrdati che la poesia vera fa battere, se mai, il cuore, non mai le mani.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "I poeti hanno abbellito agli occhi, alla memoria, al pensiero degli uomini, la terra, il mare, il cielo, l'amore, il dolore, la virtù; e gli uomini non sanno il loro nome.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "E non vide la casa, né i leoni | dormir col muso su le lunghe zampe, | né la sua dea. Ma declinava il sole, | e tutte già s'ombravano le strade.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Da' borghi sparsi le campane in tanto | si rincorron coi lor gridi argentini: | chiamano al rezzo, alla quiete, al santo | desco fiorito d'occhi di bambini.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Al camino, ove scoppia la mortella | tra la stipa, o ch'io sogno, o veglio teco: | mangio teco radicchio e pimpinella", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Al rio sottile, di tra vaghe brume, | guarda il bove coi grandi occhi: nel piano | che fugge, a un mare sempre più lontano | migrano l'acque d'un ceruleo fiume.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "San Lorenzo, io lo so perché tanto | di stelle per l'aria tranquilla | arde e cade, perché sì gran pianto | nel concavo cielo sfavilla", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "E tu, Cielo, dall'alto dei mondi | sereni, infinito, immortale, | oh! d'un pianto di stelle lo inondi | quest'atomo opaco del Male", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "E cielo e terra si mostrò qual era: || la terra ansante, livida, in sussulto; | il cielo ingombro, tragico, disfatto.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Io la felicità inseguo per monti, per piani, | pel mare, pel cielo, nel cuore, | io la vedo, già tendo le mani, | già tengo la gloria e l'amore", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Udia tra i fieni allor allor falciati | de' grilli il verso che perpetuo trema, | udiva dalle rane dei fossati | un lungo interminabile poema", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Sembra un vociare, per la calma, fioco, | di marinai, ch'ad ora ad ora giunga | tra 'l fievole sciacquio della risacca", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Scendea tra gli olmi il sole | in fascie polverose; | erano in ciel due sole | nuvole, tenui, róse: | due bianche spennellate | in tutto il ciel turchino. | Siepi di melograno, | fratte di tamerice, | il palpito lontano | d'una trebbïatrice, | l'angelus argentino...", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Manina chiusa, che nel sonno grande | stringi qualcosa, dimmi cosa ci hai! | Cosa ci ha? cosa ci ha? Vane domande: | quello che stringe, niuno saprà mai", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Come un'arca d'aromi oltremarini, | il santuario, a mezzo la scogliera, | esala ancora l'inno e la preghiera | tra i lunghi intercolunnii de' pini", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Allora... io un tempo assai lunge | felice fui molto; non ora: | ma quanta dolcezza mi giunge | da tanta dolcezza d'allora!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Nel campo mezzo grigio e mezzo nero | resta un aratro senza buoi, che pare | dimenticato, tra il vapor leggero.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Nella soffitta è solo, è nudo, muore. | Stille su stille gemono dal tetto || [...] || La notte cade, l'ombra si fa nera; | egli va, desolato, in Paradiso.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Più bello il fiore cui la pioggia estiva | lascia una stilla dove il sol si frange.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Noi mentre il mondo va per la sua strada, | noi ci rodiamo, e in cuor doppio è l'affanno, | e perché vada, e perché lento vada.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Odi, sorella, come note al core | quelle nel vespro tinnule campane | empiono l'aria quasi di sonore | grida lontane?", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Quanti quel roseo campanile bisbigli | udì, quel giorno, o strilli di rondoni | impazienti agl'inquieti figli", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Rosa di macchia, che dall'irta rama | ridi non vista a quella montanina, | che stornellando passa e che ti chiama | rosa canina", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Sappi – e forse lo sai, nel camposanto – | la bimba dalle lunghe anella d'oro, | e l'altra che fu l'ultimo tuo pianto, | sappi ch'io le raccolsi e che le adoro.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Vien per la strada un povero che il lento | passo tra foglie stridule trascina: | nei campi intuona una fanciulla al vento: | Fiore di spina!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Anch'io; ricordo, ma passò stagione; | quelle bacche a gli uccelli della frasca | invidiavo, e le purpuree more; | e l'ala, i cieli, i boschi, la canzone: | i boschi antichi, ove una foglia casca, | muta, per ogni battito di cuore", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "E nella notte nera come il nulla, || a un tratto, col fragor d'arduo dirupo | che frana, il tuono rimbombò di schianto: | rimbombò, rimbalzò, rotolò cupo, | e tacque, e poi rimareggiò rinfranto, | e poi vanì. Soave allora un canto | s'udì, di madre, e il moto di una culla.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Mettea, chi fiori non potea, le spine; | mettea le gemme l'albero più brullo: | piovea la quercia, vergognando alfine, | le vecchie foglie a' piedi del fanciullo.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Avevi i piedi ignudi su la soglia, | tremavi come un armellino in fiore, | che trema tutto al vento che lo spoglia.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Ma il torcicollo a cui nulla si cela, | avanti o dietro, e che giammai non erra, | cantava pur la lunga sua querela.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Udiano le due voci delle sere | di primavera, limpide e sonore, | così lontane che parean non vere, || così vicine che parean del cuore.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Allor s'aprì la prima stella in cielo; | e dalla terra tacita e sorpresa | si levò un trillo come un lungo stelo. || Un'altra, un altro. Ad ogni stella accesa, | un nuovo canto. Un canto senza posa | correva ardendo lungo la distesa || del cielo azzurro. – È l'usignolo, o Rosa! –", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Non siamo onde superbe, onde sommesse. | Onde, e non più. L'acqua del mare è tanta! | Siamo in un attimo, e non mai le stesse. || Ora io son quella che già là s'è franta. | E io già quella ch'ora là si frange. | L'onda che geme ora è lassù, che canta; | l'onda che ride, ai piedi tuoi già piange.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Noi siamo quello che sei tu: non siamo. | L'ombre del moto siamo. E ci son onde | anche tra voi, figli del rosso Adamo? | Non sono. È il vento ch'agita, confonde, | mesce, alza, abbassa; è il vento che ci schiaccia | contro gli scogli e rotola alle sponde.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Usignol della nebbia, che i nostri orti | visiti quando non c'è più che bruchi, | tu che ci lodi il verno che ci porti; || e ti fai cuore, e vieni e vai, t'imbuchi, | t'infraschi, e cerchi e fai sentire un canto | appena trovi sanguini o sambuchi:", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "girare i boschi, bere ai puri fonti | della sua terra, e te godere ancora, | sole, che così bello oggi tramonti, || e, dopo ancor l'avemaria, quest'ora | chiara e la sera che s'addorme e pare | sognar, sui monti, d'essere l'aurora.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Chi vede mai le pratelline in boccia? | Ed un bel dì le pratelline in fiore | empiono il prato e stellano la roccia. || Chi ti sapeva, o bianco fior d'amore | chiuso nel cuore? E tutta, all'improvviso, | la nera terra ecco mutò colore.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "dolore è più dolor, se tace", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Chi piange in sogno, è giunto a ciò che vuole, | è giunto alfine a tutto ciò che implora | invano.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Fioria la zucca, arsivano i piselli, | nell'orto. Le ciliege erano andate: | per San Giovanni avevano i giannelli.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "La terra è buona: dura, ma fedele; | ma è una barca, il sole per timone, | e bianche e nere nuvole per vele. || Ci vuole il cielo: tutto a sua stagione; | e freddo, caldo, dolce, aspro, ci vuole, | e i lampi e tuoni e il fumido acquazzone.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Si sa: marzo va secco, il gran fa cesto. | Il gran, per uno pallido e sottile, | più ciuffi mise, quanto più fu pesto.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Chi prega è santo, ma chi fa, più santo", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Il meglio, il fiore dell'annata intera, | noi manderemo subito al molino; | che l'abbia a giorno e che lo renda a sera.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Nere le mete: solo qualche lampo | facean le paglie, come se un tesoro | fosse disperso qua e là nel campo.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Che cosa avrebbe egli da lei voluto? | Qual piaga dare tenera e mortale | a quelle carni bianche, di velluto? || Qual pianto fa di quel ch'è ora, e quale | rimpianto mai di quel ch'un giorno fu!... — | Col mesto verso eternamente uguale || le rispondeva di lontano il chiù.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Il poco è molto a chi non ha che il poco:", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Ciò che secca e che cade e che s'oblia, | io lo raccolgo: ancora ciò che al cuore | si stacca triste e che poi fa che sia | morbido il sonno, il giorno che si muore.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Azimo santo e povero dei mesti | agricoltori, il pane del passaggio | tu sei, che s'accompagna all'erbe agresti; || il pane, che, verrà tempo, e nel raggio | del cielo, sulla terra alma, gli umani | lavoreranno nel calendimaggio.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "E la luna calante batté gialla | sull'impannata. Netta, senza brume, | stava, sul liscio mar di neve, a galla. || L'immensa taiga biancheggiava al lume. | Qualche betulla nuda, qualche cono | d'abete, e solchi d'ombra d'un gran fiume.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Fole! | L'uomo non vola, o garrula ghiandaia, | come gli uccelli e come le parole!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "O tacito paese | sopra le nubi! O isola del cielo, | che fiorisci e sfiorisci d'ogni mese!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "E non c'è dì senz'alba, e l'alba è l'ora | più bella; e senza fiore non c'è frutto, | e il fiore è bello, il fiore è il più che odora.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Io l'ho veduta. Corre sempre, vola, | passa. Ma mentre va, che non mai posa, | a noi non volge che una parte sola. || Vediamo, noi, nel cielo azzurro o rosa, | sempre quelle montagne, sempre quelle | paludi. Sempre. Ma di là? Che cosa | è mai di là, verso le grandi stelle?", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Più che mezza la luna era, e più ore | restava su, tra l'iridato alone, | e le notti imbevea del suo pallore.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "La paradisa ha pigne lunghe e chiare, | e tutti d'oro sono i chicchi, e hanno | il sole dentro, il sole che traspare.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Il bello è bello, ma non dura.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "La gente era venuta sull'aurora | quando la guazza o la nebbietta inerte | vapora in cielo, e il cielo si colora.", Author = "Giovanni Pascoli" },
        };
    }
